import json
n=17;m=8
g=[[0]*n for _ in range(n)]
for r in range(n):
 if r<=m:
  g[r][m-r]=2; g[r][m+r]=2
# early pattern observed in demos, then repeated diagonal lattice
special={3:[m-1],4:[m],5:[m-3,m+1],6:[m-2,m+2]}
for r in range(3,n):
 cols=special.get(r,[c for c in range(n) if (c-r-m)%4==0])
 for c in cols:
  if g[r][c]==0: g[r][c]=1
assert len(g)==17 and all(len(row)==17 for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

